import React from 'react';
import { ChevronRight } from 'lucide-react';
import { motion } from 'framer-motion';
import { useNavigate } from 'react-router-dom';
import '../styles/cards.css';

export default function GroupCard({ group, onExpenseClick }) {
  const navigate = useNavigate();
  const memberCount = group.members?.length || 0;
  const totalExpenses = group.expenses?.reduce((sum, e) => sum + e.amount, 0) || 0;

  return (
    <motion.div
      className="group-card"
      whileHover={{ y: -4, boxShadow: '0 20px 60px rgba(108, 99, 255, 0.2)' }}
      transition={{ duration: 0.3 }}
    >
      <div className="card-header">
        <div className="card-icon">👥</div>
        <div className="card-title-section">
          <h3>{group.name}</h3>
          <p className="card-meta">{memberCount} members</p>
        </div>
      </div>

      <div className="card-stats">
        <div className="stat-item">
          <span className="stat-label">Total</span>
          <span className="stat-value">${totalExpenses.toFixed(2)}</span>
        </div>
        <div className="stat-item">
          <span className="stat-label">Your Share</span>
          <span className="stat-value">$--</span>
        </div>
      </div>

      <div className="card-members">
        <div className="members-preview">
          {group.members?.slice(0, 3).map((member, i) => (
            <div key={member._id} className="member-mini" style={{ zIndex: 3 - i }}>
              {member.name.charAt(0)}
            </div>
          ))}
          {memberCount > 3 && <div className="member-mini more">+{memberCount - 3}</div>}
        </div>
      </div>

      <div className="card-actions">
        <button
          className="btn-action"
          onClick={onExpenseClick}
        >
          Add Expense
        </button>
        <button
          className="btn-action secondary"
          onClick={() => navigate(`/group/${group._id}`)}
        >
          <ChevronRight size={18} />
        </button>
      </div>
    </motion.div>
  );
}
